package android.view;import java.util.*; public class ViewGroup extends View {public static class LayoutParams {public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public static class MarginLayoutParams extends LayoutParams {public int bottomMargin;public MarginLayoutParams(int w,int h){super(w,h);}}public final List<View> children=new ArrayList<View>();public void addView(View v,LayoutParams p){children.add(v);v.parent=this;v.setLayoutParams(p);}public void removeView(View v){children.remove(v);v.parent=null;}public View getChildAt(int i){return children.get(i);}}
